import test from 'node:test';import assert from 'node:assert/strict';import {encounter,enemyIntent} from '../src/encounters.js';import {Game,ROOMS} from '../src/engine.js';import {recapData,renderRunRecap} from '../src/recap.js';
test('late encounters expose every opponent immediately and preserve combat victory',()=>{for(let room=5;room<=12;room++){const g=new Game({seed:42});g.room=room;g.setupRoom();g.start();assert.ok(g.enemies.length>ROOMS[room-1].types.length);for(const e of g.enemies){assert.ok(e.x>=35+e.r&&e.x<=g.width-35);assert.ok(e.alive);g.hitEnemy(e,10000);}g.deathQueue=[];g.update(1/60,{});assert.equal(g.clearReason,'combat');}});
test('guarded groups wake on approach or damage; damaged ranged enemies stop fleeing',()=>{let e={type:'spitter',x:100,y:100,hp:36,maxHp:36,armor:24,maxArmor:24,guarded:true,engaged:false,phase:0};assert.equal(enemyIntent(e,{x:800,y:400}).attack,false);e.hp=30;assert.equal(enemyIntent(e,{x:800,y:400}).attack,true);assert.equal(enemyIntent(e,{x:110,y:100}).x,0);assert.ok(encounter(12,['boss'],600,800).every(e=>e.x>=70&&e.y<=730));});
test('recap distinguishes actual reactions from equipped but unused synergies',()=>{const g=new Game();g.mods.electric=3;g.loadout=['electric'];assert.equal(recapData(g).combos.length,0);g.stats.electricHits=7;assert.deepEqual(recapData(g).combos,[{name:'电弧命中',count:7}]);assert.match(renderRunRecap(g),/本局|清洁手帐/);assert.match(renderRunRecap(g),/重新获取/);});
test('a newly completed evolution announces exactly once when crossing its threshold',()=>{const g=new Game();g.start();g.mods.brush=1;g.mods.electric=2;g.state='upgrade';g.offers=['brush'];g.drainEvents();g.chooseUpgrade('brush');assert.equal(g.drainEvents().filter(e=>e.type==='evolution'&&e.name==='电动洗地风暴').length,1);g.state='upgrade';g.offers=['brush'];g.chooseUpgrade('brush');assert.equal(g.drainEvents().filter(e=>e.type==='evolution').length,0);});
